head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnDataListInfo]<br/>Body Column 정보를 사용하여 특정 Column 에 바인딩된 DataList 정보를 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - 1줄 = col1(인덱스0:text) / col2(인덱스1:select, DataList dlt_grade 바인딩)
//  - 2줄 = col3(인덱스2:text) / col4(인덱스3:checkcombobox, DataList dlt_grade 바인딩)
//  - Row 가 MultiLine 이어도 col1~col4 는 각각 고유 인덱스(0~3) 를 가짐
//  - DataList 바인딩 컬럼(select=1 / checkcombobox=3) 은 getColumnDataListInfo 시 객체 반환
//  - text 컬럼(0/2) 은 DataList 바인딩 아님 -> null 반환
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨. 1줄 col1(0:text)/col2(1:select, dlt_grade 바인딩), 2줄 col3(2:text)/col4(3:checkcombobox, dlt_grade 바인딩) 고유 인덱스. DataList(dlt_grade) 는 code/label 컬럼. 데이터 Row 3개.\n[절차] columnInfo(0~3) 선택 후 (getColumnDataListInfo 실행) -> 선택한 고유 인덱스로 getColumnDataListInfo 호출하여 반환값과 getColumnID(인덱스) 매핑 확인.\n[확인] MultiLine 이어도 col1~col4 는 고유 인덱스(0~3) 로 각각 정확히 지목됨. DataList 바인딩 컬럼(idx1:select / idx3:checkcombobox) 은 객체(nodeset:data:dlt_grade,id:dlt_grade,value:code,label:label) 반환, text 컬럼(idx0/idx2) 은 null 반환."', '', 'label1');

    // 아이템 옵션용 DataList (code/label) 동적 생성 -> select/checkcombobox 컬럼이 바인딩
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "code": "A", "label": "A등급" },
        { "code": "B", "label": "B등급" },
        { "code": "C", "label": "C등급" },
        { "code": "D", "label": "D등급" }
    ], false);

    // dataList 생성 + 초기값 바인딩 (col1:text / col2:select(A/B/C) / col3:text / col4:checkcombobox)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "A", "col3": "김영업", "col4": "A" },
        { "col1": "부산 해운대점", "col2": "B", "col3": "이판매", "col4": "B,C" },
        { "col1": "대구 수성점", "col2": "C", "col3": "박상담", "col4": "C" }
    ]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    //  - 1줄 : col1(0:text) / col2(1:select, dlt_grade 바인딩)
    //  - 2줄 : col3(2:text) / col4(3:checkcombobox, dlt_grade 바인딩)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:560px;height:340px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="지점명(text)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="등급(select)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="담당자(text)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="우대등급(checkcombobox)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // index 0 : col1 (text) - DataList 바인딩 아님 -> null
    strTarget += '<w2:column width="280" inputType="text" id="col1" dataList="col1"></w2:column>';
    // index 1 : col2 (select, 1줄 마지막, 고유 인덱스 1) - DataList(dlt_grade) 바인딩 itemset
    strTarget += '<w2:column width="*" inputType="select" id="col2" dataList="col2">';
    strTarget += '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';
    strTarget += '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // index 2 : col3 (text, 2줄 첫 컬럼, 고유 인덱스 2) - DataList 바인딩 아님 -> null
    strTarget += '<w2:column width="280" inputType="text" id="col3" dataList="col3"></w2:column>';
    // index 3 : col4 (checkcombobox, 2줄 마지막, 고유 인덱스 3) - DataList(dlt_grade) 바인딩 itemset
    strTarget += '<w2:column width="*" inputType="checkcombobox" id="col4" dataList="col4">';
    strTarget += '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';
    strTarget += '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// [실행] getColumnDataListInfo : 선택한 컬럼(고유 누적 인덱스) 에 바인딩된 DataList 정보를 반환
//  - MultiLine(2줄) 이어도 col1~col4 는 고유 인덱스(0~3) 로 정확히 지목됨
//  - DataList 바인딩 컬럼(idx1:select / idx3:checkcombobox) -> 객체 {nodeset,id,value,label} 반환
//  - text 컬럼(idx0/idx2) 은 DataList 바인딩 아님 -> null 반환
//  - getColumnID(인덱스) 매핑도 함께 출력하여 인덱스 -> 컬럼 ID 대응 확인
scwin.btn_getColumnDataListInfo_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let colID = target1.getColumnID(columnInfo);   // MultiLine Row 에서도 col1~col4 는 고유 인덱스(0~3)
    let info = target1.getColumnDataListInfo(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnDataListInfo(" + columnInfo + ") [고유 인덱스 " + columnInfo + " -> getColumnID : " + colID + "] -> 반환값 : " + JSON.stringify(info));
}
